<script setup lang="ts">
import {onMounted,ref} from 'vue';import {ElCard,ElAlert,ElButton,ElForm,ElFormItem,ElInputNumber,ElInput,ElSelect,ElOption,ElMessage,ElMessageBox} from 'element-plus';import {requestClient} from '#/api/request';import BusinessPageHeader from '#/components/BusinessPageHeader.vue';
type Setting={key:string;revision:number;value:Record<string,any>};const rows=ref<Setting[]>([]),loading=ref(false),saving=ref(''),error=ref('');
const names:Record<string,string>={recommendation:'推荐规则',model:'模型参数',prompts:'提示模板扩展'};
async function load(){loading.value=true;error.value='';try{rows.value=await requestClient.get('/admin/config/runtime')}catch{error.value='配置加载失败，请重试'}finally{loading.value=false}}
async function save(row:Setting){try{await ElMessageBox.confirm('保存后对新请求生效，已进行中的对话不会重放。','更新'+names[row.key]);saving.value=row.key;await requestClient.put('/admin/config/runtime',row);ElMessage.success('配置已更新');await load()}catch{}finally{saving.value=''}}
onMounted(load);
</script>
<template><div class="runtime-page"><BusinessPageHeader eyebrow="SERVICE SETTINGS" title="推荐与陪伴配置" description="调整推荐排序与表达方式。安全边界始终生效，密钥只保存在服务端。"><ElButton :loading="loading" :disabled="!!saving" @click="load">重新读取</ElButton></BusinessPageHeader><ElAlert v-if="error" type="error" :title="error" :closable="false"/><div class="config-grid"><ElCard v-for="r in rows" :key="r.key" shadow="never"><template #header><div class="card-heading"><h2>{{names[r.key]}}</h2><span>修订 {{r.revision}}</span></div></template><ElForm label-position="top" :disabled="!!saving||loading"><template v-if="r.key==='recommendation'"><ElFormItem label="每次推荐数量"><ElInputNumber v-model="r.value.count" :min="1" :max="6"/></ElFormItem><ElFormItem label="偏好标签权重"><ElInputNumber v-model="r.value.tagWeight" :min="0" :max="2" :step="0.1"/></ElFormItem><ElFormItem label="易上手权重"><ElInputNumber v-model="r.value.easeWeight" :min="0" :max="2" :step="0.1"/></ElFormItem><ElFormItem label="材料安全范围"><ElSelect v-model="r.value.maxSafety"><ElOption value="LOW" label="仅低风险材料"/><ElOption value="GUIDED" label="低风险及需带领者指导的项目"/></ElSelect></ElFormItem><p>未标注及高风险项目不会进入自动推荐；请在项目管理中维护安全说明。</p></template><template v-else-if="r.key==='model'"><ElFormItem label="表达变化程度（temperature）"><ElInputNumber v-model="r.value.temperature" :min="0" :max="1" :step="0.1"/></ElFormItem><ElFormItem label="单次生成长度上限（tokens）"><ElInputNumber v-model="r.value.maxTokens" :min="128" :max="2048" :step="128"/></ElFormItem><p>仅影响已接入的大模型。服务地址、模型名称和密钥由服务端环境配置管理。</p></template><template v-else><ElAlert title="这些内容追加到既有模板，不替换安全提示。请勿填入密钥或用户私人信息。" :closable="false"/><ElFormItem v-for="(label,key) in {companion:'陪伴对话',recommendation:'推荐说明',work:'作品寄语'}" :key="key" :label="label"><ElInput v-model="r.value[key]" type="textarea" :rows="3" maxlength="2000" show-word-limit/></ElFormItem></template><ElButton type="primary" :loading="saving===r.key" @click="save(r)">保存{{names[r.key]}}</ElButton></ElForm></ElCard></div><p>本系统不能替代专业心理咨询</p></div></template>
<style scoped>.runtime-page{padding:24px}.config-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:24px}.config-grid>:last-child{grid-column:1/-1}.card-heading{display:flex;align-items:center;justify-content:space-between}.card-heading h2{font-size:18px;font-weight:600}.card-heading span,p{font-size:13px;color:var(--el-text-color-secondary);line-height:1.8}@media(max-width:700px){.runtime-page{padding:16px}.config-grid{grid-template-columns:1fr}}</style>
